# Construct the output by scaling and reflecting the 3x3 tile template around each 2 marker.
N=27
g=[[4]*N for _ in range(N)]
for r in range(N): g[r][13]=1
for c in range(N): g[13][c]=1
# top-left source template, tile size 2, origin (3,1)
T=[[None,3,6],[8,8,2],[None,None,1]]
for tr,row in enumerate(T):
    for tc,col in enumerate(row):
        if col is not None:
            for dr in range(2):
                for dc in range(2): g[3+tr*2+dr][1+tc*2+dc]=col
# destination configurations: panel, tile size, seed top-left, transform
configs=[('TR',3,(4,19),'H'),('BR',4,(19,18),'HV'),('BL',1,(21,5),'V')]
for name,n,(ar,ac),tf in configs:
    M=[row[:] for row in T]
    if 'V' in tf: M=M[::-1]
    if 'H' in tf: M=[row[::-1] for row in M]
    sr,sc=1,2
    if 'V' in tf: sr=2-sr
    if 'H' in tf: sc=2-sc
    for tr,row in enumerate(M):
        for tc,col in enumerate(row):
            if col is None: continue
            r0=ar+(tr-sr)*n; c0=ac+(tc-sc)*n
            # Clip to the appropriate 13x13 quadrant.
            rlo,rhi=(0,13) if name in ('TR','TL') else (14,27)
            clo,chi=(14,27) if name in ('TR','BR') else (0,13)
            for r in range(r0,r0+n):
                for c in range(c0,c0+n):
                    if rlo<=r<rhi and clo<=c<chi:
                        g[r][c]=col
print('\n'.join(' '.join(map(str,row)) for row in g))
